// Changes: Behaviour of the LL grid helpers – the reduced table picked from the shared model and the cell detail line.

import { describe, expect, it } from 'vitest'
import type { TableModel } from '#/lib/tableModel'
import { cellDetail, pickTableModel } from '#/lib/tableModel'

const cell = (text: string, title = '', conflict = false) => ({ text, title, conflict })
const model: TableModel = {
  title: 'LL tabuľka',
  header: ['', 'a', 'b', '$'],
  rows: [
    { head: 'S', cells: [cell('1', '1: S → a A'), cell(''), cell('')] },
    { head: 'A', cells: [cell(''), cell('2, 3', '2: A → b\n3: A → ε', true), cell('3', '3: A → ε')] },
  ],
}

describe('pickTableModel', () => {
  it('keeps only the given rows and columns, in the model order', () => {
    const picked = pickTableModel(model, ['A'], ['$', 'b'])
    expect(picked.header).toEqual(['', 'b', '$'])
    expect(picked.rows).toEqual([{ head: 'A', cells: [cell('2, 3', '2: A → b\n3: A → ε', true), cell('3', '3: A → ε')] }])
    expect(picked.title).toBe('LL tabuľka')
  })
})

describe('cellDetail', () => {
  it('names the cell and its rules', () => {
    expect(cellDetail(model, 0, 0)).toBe('[S, a] → 1: S → a A')
  })

  it('marks a conflict and lists every rule of the cell', () => {
    expect(cellDetail(model, 1, 1)).toBe('[A, b] → konflikt: 2: A → b; 3: A → ε')
  })

  it('explains an empty cell', () => {
    expect(cellDetail(model, 0, 2)).toBe('[S, $] → prázdna bunka (syntaktická chyba)')
  })

  it('is empty outside the table', () => {
    expect(cellDetail(model, 5, 0)).toBe('')
  })
})
